build_cmd:
PLATFORMIO_BUILD_UNFLAGS="-DMILLIS_USE_TIMERB1" PLATFORMIO_BUILD_FLAGS="-Wl,-Map=.pio/build/V450_2K4/firmware.map" pio run -d ATTINYCellModule -e V450_2K4 && mkdir -p /home/runner/membrowse-ld && cp "$(ls -d $HOME/.platformio/packages/toolchain-atmelavr*/avr/lib/ldscripts/avrxmega3.xn | head -1)" /home/runner/membrowse-ld/avrxmega3.xn && printf 'MEMORY
{
  mapped_flash (r) : ORIGIN = 0x8000, LENGTH = 16K
}
' > /home/runner/membrowse-ld/attiny1624-mapped-flash.ld

